+        core->first_sample_ms = sample->timestamp_ms;
+        core->last_sample_ms = sample->timestamp_ms;
+        core->baseline_c = sample->temp_c;
+        core->filtered_temp_c = sample->temp_c;
+        core->last_temp_c = sample->temp_c;
+        core->max_temp_c = sample->temp_c;
+    } else {
