+        const float dt_s = (float)dt_ms / 1000.0f;
+        const float alpha = clampf(core->cfg.filter_alpha, 0.01f, 1.0f);
+        core->filtered_temp_c += alpha * (sample->temp_c - core->filtered_temp_c);
+        if (dt_s >= 0.05f && dt_s <= 120.0f) {
+            core->rate_c_per_min = (core->filtered_temp_c - core->last_temp_c) / dt_s * 60.0f;
