+const char *WIFI_SSID = "替换为你的WiFi名称";
+const char *WIFI_PASSWORD = "替换为你的WiFi密码";
+IPAddress GEMINI_IP(192, 168, 1, 50);  // 改成 Gemini-S1 在同一局域网的 IP
+constexpr uint16_t GEMINI_PORT = 3333;
+constexpr uint16_t LOCAL_PORT = 3334;
+constexpr char DEVICE_ID[] = "KitchenGuardian_001";
+
+constexpr int SDA_PIN = 21;
+constexpr int SCL_PIN = 22;
+/* 没有实体炉火开关时保持 -1，程序按温度推断 heating；有开关可改为实际 GPIO。 */
+constexpr int STOVE_ON_PIN = -1;
+/* 如果有按键/霍尔开关，可以在这里接入；-1 表示按温差自动判断锅具存在。 */
+constexpr int POT_PRESENT_PIN = -1;
+
+Adafruit_MLX90614 mlx = Adafruit_MLX90614();
+WiFiUDP udp;
+uint32_t lastSendMs = 0;
+float lastTempC = NAN;
+uint32_t lastTempMs = 0;
+
+static void connect_wifi()
+{
+    if (WiFi.status() == WL_CONNECTED) return;
+    WiFi.mode(WIFI_STA);
+    WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
+    Serial.printf("Connecting WiFi to %s", WIFI_SSID);
+    const uint32_t start = millis();
+    while (WiFi.status() != WL_CONNECTED && millis() - start < 15000u) {
+        delay(250);
+        Serial.print('.');
+    }
+    Serial.println();
+    if (WiFi.status() == WL_CONNECTED) {
+        Serial.print("WiFi connected, ESP32 IP: ");
+        Serial.println(WiFi.localIP());
+    } else {
+        Serial.println("WiFi connect timeout; will retry");
+    }
+}
+
+static int infer_pot_present(float objectTempC, float ambientTempC)
+{
+    if (POT_PRESENT_PIN >= 0) return digitalRead(POT_PRESENT_PIN) != LOW;
+    return isfinite(objectTempC) && isfinite(ambientTempC) && objectTempC - ambientTempC > 5.0f;
+}
+
+static int infer_heating(float objectTempC, float rateCPerMin, int potPresent)
+{
+    if (!potPresent) return 0;
+    if (STOVE_ON_PIN >= 0) return digitalRead(STOVE_ON_PIN) == HIGH;
+    /* 无炉火开关时的原型推断：锅温高于 40℃ 就视为处于加热/保温流程。
+       正式作品建议增加一个开关输入或在界面增加“开始烹饪”按钮。 */
+    return objectTempC > 40.0f || rateCPerMin > 0.5f;
+}
+
+static void send_telemetry(float objectTempC, float ambientTempC,
+                           float rateCPerMin, int heating, int potPresent)
+{
+    if (WiFi.status() != WL_CONNECTED) return;
+    char payload[320];
+    const int n = snprintf(
+        payload, sizeof(payload),
+        "{\"device_id\":\"%s\",\"timestamp_ms\":%lu,\"temp_c\":%.2f,"
+        "\"ambient_humidity\":-1,\"heating\":%d,\"pot_present\":%d,"
+        "\"ambient_c\":%.2f,\"rate_c_per_min\":%.2f}",
+        DEVICE_ID, (unsigned long)millis(), objectTempC, heating, potPresent,
+        ambientTempC, rateCPerMin);
+    if (n <= 0 || n >= (int)sizeof(payload)) return;
+    udp.beginPacket(GEMINI_IP, GEMINI_PORT);
+    udp.write((const uint8_t *)payload, (size_t)n);
+    udp.endPacket();
+    Serial.println(payload);
+}
+
+void setup()
+{
+    Serial.begin(115200);
+    delay(300);
+    Wire.begin(SDA_PIN, SCL_PIN);
+    if (STOVE_ON_PIN >= 0) pinMode(STOVE_ON_PIN, INPUT_PULLUP);
+    if (POT_PRESENT_PIN >= 0) pinMode(POT_PRESENT_PIN, INPUT_PULLUP);
+    if (!mlx.begin()) {
+        Serial.println("MLX90614 not found. Check VIN/GND/SDA/SCL and I2C address.");
+        while (true) delay(1000);
+    }
+    udp.begin(LOCAL_PORT);
+    connect_wifi();
+}
+
+void loop()
+{
+    connect_wifi();
+    const uint32_t now = millis();
+    if (now - lastSendMs < 1000u) {
+        delay(20);
+        return;
+    }
+    lastSendMs = now;
+
+    const float objectTempC = mlx.readObjectTempC();
+    const float ambientTempC = mlx.readAmbientTempC();
+    float rateCPerMin = 0.0f;
+    if (isfinite(lastTempC) && lastTempMs != 0 && now > lastTempMs) {
+        rateCPerMin = (objectTempC - lastTempC) / ((float)(now - lastTempMs) / 60000.0f);
+    }
+    lastTempC = objectTempC;
+    lastTempMs = now;
+    const int potPresent = infer_pot_present(objectTempC, ambientTempC);
+    const int heating = infer_heating(objectTempC, rateCPerMin, potPresent);
+    send_telemetry(objectTempC, ambientTempC, rateCPerMin, heating, potPresent);
+}
*** End Patch";
