/*
 * Gemini-S1/openvela 通用 UDP 接收端。
 *
 * 默认监听 UDP 3333。把 core/ 和本目录加入官方 openvela app 的编译路径，
 * 再按 SDK 示例注册 main() 即可。代码只使用 POSIX socket 接口，避免依赖
 * 某一个版本的 RIVOTEK 工程目录。
 */

#include "pot_guard_core.h"
#include "protocol.h"
#include "platform_hooks.h"

#if defined(_WIN32)
#include <winsock2.h>
#include <ws2tcpip.h>
#else
#include <arpa/inet.h>
#endif
#include <errno.h>
#if !defined(_WIN32)
#include <netinet/in.h>
#endif
#include <stdio.h>
#include <string.h>
#if !defined(_WIN32)
#include <sys/socket.h>
#endif
#if !defined(_WIN32)
#include <sys/time.h>
#include <unistd.h>
#endif

#ifndef GG_UDP_PORT
#define GG_UDP_PORT 3333
#endif

static void gg_close_socket(int fd)
{
#if defined(_WIN32)
    closesocket((SOCKET)fd);
#else
    close(fd);
#endif
}

static void dispatch_events(uint32_t events, PgCore *core)
{
    const uint32_t bits[] = {
        PG_EVENT_CLASSIFIED, PG_EVENT_POT_INSERTED, PG_EVENT_POT_REMOVED,
        PG_EVENT_DRY_RISK, PG_EVENT_ALARM_ON, PG_EVENT_ALARM_OFF,
        PG_EVENT_SENSOR_ERROR, PG_EVENT_TIMER_EXPIRED, PG_EVENT_REMINDER
    };
    for (size_t i = 0; i < sizeof(bits) / sizeof(bits[0]); ++i) {
        if (events & bits[i]) gg_platform_event(bits[i], core);
    }
}

int gemini_guard_receiver_main(int argc, char **argv)
{
    (void)argc;
    (void)argv;
#if defined(_WIN32)
    WSADATA wsa;
    if (WSAStartup(MAKEWORD(2, 2), &wsa) != 0) return 1;
#endif
    int fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (fd < 0) {
        printf("socket failed errno=%d\n", errno);
        return 1;
    }

    int reuse = 1;
    (void)setsockopt(fd, SOL_SOCKET, SO_REUSEADDR,
#if defined(_WIN32)
                     (const char *)&reuse,
#else
                     &reuse,
#endif
                     sizeof(reuse));
#if defined(_WIN32)
    DWORD timeout_ms = 200;
    (void)setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO,
                     (const char *)&timeout_ms, sizeof(timeout_ms));
#else
    struct timeval timeout;
    timeout.tv_sec = 0;
    timeout.tv_usec = 200000;
    (void)setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout));
#endif

    struct sockaddr_in local;
    memset(&local, 0, sizeof(local));
    local.sin_family = AF_INET;
    local.sin_addr.s_addr = htonl(INADDR_ANY);
    local.sin_port = htons(GG_UDP_PORT);
    if (bind(fd, (struct sockaddr *)&local, sizeof(local)) < 0) {
        printf("bind UDP %d failed errno=%d\n", GG_UDP_PORT, errno);
        gg_close_socket(fd);
        return 1;
    }

    PgConfig cfg;
    PgCore core;
    pg_default_config(&cfg);
    pg_init(&core, &cfg);
    gg_platform_init();
    printf("gemini_guard_receiver: listening UDP %d\n", GG_UDP_PORT);

    for (;;) {
        char buf[512];
        const int n = recvfrom(fd, buf, (int)sizeof(buf) - 1, 0, NULL, NULL);
        const uint64_t now_ms = protocol_now_ms();
        if (n > 0) {
            buf[n] = '\0';
            PgTimerCommand timer_cmd;
            if (protocol_parse_timer(buf, &timer_cmd)) {
                const uint32_t timer_event = pg_timer_start(
                    &core, now_ms, timer_cmd.seconds, timer_cmd.label);
                dispatch_events(timer_event, &core);
                gg_platform_show_status(&core);
                continue;
            }

            PgTelemetry telemetry;
            if (!protocol_parse_telemetry(buf, &telemetry)) {
                printf("invalid JSON: %s\n", buf);
                continue;
            }
            PgSample sample;
            sample.timestamp_ms = telemetry.timestamp_ms;
            sample.temp_c = telemetry.temp_c;
            sample.humidity_pct = telemetry.humidity_pct;
            sample.heating = telemetry.heating;
            sample.pot_present = telemetry.pot_present;
            sample.valid = 1;
            const uint32_t events = pg_update(&core, &sample);
            dispatch_events(events, &core);
            gg_platform_show_status(&core);
        } else if (n < 0) {
#if defined(_WIN32)
            const int socket_error = WSAGetLastError();
            if (socket_error != WSAETIMEDOUT && socket_error != WSAEINTR) {
                printf("recvfrom failed WSA error=%d\n", socket_error);
            }
#else
            if (errno != EAGAIN && errno != EWOULDBLOCK && errno != EINTR) {
                printf("recvfrom failed errno=%d\n", errno);
            }
#endif
        }

        const uint32_t timer_events = pg_timer_update(&core, now_ms);
        dispatch_events(timer_events, &core);
    }
}

