void gg_platform_event(uint32_t event_bit, const PgCore *core)
{
    const char *name = "EVENT";
    switch (event_bit) {
        case PG_EVENT_CLASSIFIED: name = "锅具热响应已判断"; break;
        case PG_EVENT_POT_INSERTED: name = "检测到锅具"; break;
        case PG_EVENT_POT_REMOVED: name = "锅具移开"; break;
        case PG_EVENT_DRY_RISK: name = "防干烧预警"; break;
        case PG_EVENT_ALARM_ON: name = "危险报警"; break;
        case PG_EVENT_ALARM_OFF: name = "报警关闭"; break;
        case PG_EVENT_SENSOR_ERROR: name = "传感器错误"; break;
        case PG_EVENT_TIMER_EXPIRED: name = "定时提醒到期"; break;
        case PG_EVENT_REMINDER: name = "定时提醒已设置"; break;
        default: break;
    }
    printf("[event] %s (%u), stage=%s, temp=%.1fC\n", name, event_bit,
           core ? pg_stage_name(core->stage) : "-",
           core ? core->filtered_temp_c : 0.0f);

    /* TODO(Gemini-S1):
     *   PG_EVENT_DRY_RISK / PG_EVENT_ALARM_ON -> 蜂鸣器和红色 LED
     *   PG_EVENT_TIMER_EXPIRED -> 短促提示音
