    float filtered_temp_c;
    float last_temp_c;
    float rate_c_per_min;
    float max_temp_c;
    float rise_sum_c_per_min;
    uint32_t rate_samples;
    float max_rate_c_per_min;
    PgTimer timer;
} PgCore;

