static const PgProfile PROFILE_UNKNOWN = {
    PG_POT_UNKNOWN, "未知热响应", 30.0f, 8.0f, 240.0f
};
static const PgProfile PROFILE_FAST = {
    PG_POT_FAST, "快速导热型", 45.0f, 12.0f, 220.0f
};
static const PgProfile PROFILE_STANDARD = {
    PG_POT_STANDARD, "标准导热型", 35.0f, 9.0f, 240.0f
};
static const PgProfile PROFILE_SLOW = {
    PG_POT_SLOW, "慢速导热型", 30.0f, 6.0f, 250.0f
};

static float clampf(float value, float low, float high)
{
    if (value < low) return low;
    if (value > high) return high;
    return value;
}

void pg_default_config(PgConfig *cfg)
{
    if (!cfg) return;
    cfg->classification_window_ms = 30000u;
    cfg->dry_risk_hold_ms = 8000u;
    cfg->alarm_hold_ms = 5000u;
    cfg->boiling_learn_ms = 15000u;
    cfg->filter_alpha = 0.25f;
    cfg->heating_rate_c_per_min = 2.5f;
    cfg->boiling_rate_abs_c_per_min = 1.5f;
    cfg->default_boiling_ref_c = 100.0f;
    cfg->absolute_cutoff_c = 240.0f;
}

const PgProfile *pg_profile_for_class(PgPotClass pot_class)
{
    switch (pot_class) {
        case PG_POT_FAST: return &PROFILE_FAST;
        case PG_POT_STANDARD: return &PROFILE_STANDARD;
        case PG_POT_SLOW: return &PROFILE_SLOW;
        default: return &PROFILE_UNKNOWN;
    }
}

const char *pg_stage_name(PgStage stage)
{
    switch (stage) {
        case PG_STAGE_WAITING: return "WAITING";
        case PG_STAGE_HEATING: return "HEATING";
        case PG_STAGE_NORMAL: return "NORMAL";
        case PG_STAGE_DRY_RISK: return "DRY_RISK";
        case PG_STAGE_ALARM: return "ALARM";
        case PG_STAGE_SENSOR_ERROR: return "SENSOR_ERROR";
        default: return "UNKNOWN";
    }
}

const char *pg_class_name(PgPotClass pot_class)
{
    return pg_profile_for_class(pot_class)->name;
}

static void reset_measurement_cycle(PgCore *core, const PgSample *sample)
{
    core->stage = PG_STAGE_HEATING;
    core->classified = 0;
    core->pot_class = PG_POT_UNKNOWN;
    core->profile = *pg_profile_for_class(PG_POT_UNKNOWN);
    core->first_sample_ms = sample->timestamp_ms;
    core->last_sample_ms = sample->timestamp_ms;
    core->boiling_candidate_start_ms = 0;
    core->boiling_ref_valid = 0;
    core->baseline_c = sample->temp_c;
    core->boiling_ref_c = core->cfg.default_boiling_ref_c;
    core->filtered_temp_c = sample->temp_c;
    core->last_temp_c = sample->temp_c;
    core->rate_c_per_min = 0.0f;
    core->max_temp_c = sample->temp_c;
    core->rise_sum_c_per_min = 0.0f;
    core->rate_samples = 0;
    core->max_rate_c_per_min = 0.0f;
    core->dry_risk_start_ms = 0;
    core->alarm_start_ms = 0;
    core->dry_risk_latched = 0;
    core->alarm_latched = 0;
}

void pg_init(PgCore *core, const PgConfig *cfg)
{
    if (!core) return;
    memset(core, 0, sizeof(*core));
    if (cfg) {
        core->cfg = *cfg;
    } else {
        pg_default_config(&core->cfg);
    }
    core->stage = PG_STAGE_WAITING;
    core->pot_class = PG_POT_UNKNOWN;
    core->profile = *pg_profile_for_class(PG_POT_UNKNOWN);
}

static void classify_if_ready(PgCore *core, uint64_t now_ms, uint32_t *events)
{
    if (core->classified || !core->pot_present || !core->has_sample) return;
    if (now_ms - core->first_sample_ms < core->cfg.classification_window_ms) return;
    if (!core->heating && core->max_rate_c_per_min < core->cfg.heating_rate_c_per_min) return;

    float avg_positive_rate = 0.0f;
    if (core->rate_samples > 0) {
        avg_positive_rate = core->rise_sum_c_per_min / (float)core->rate_samples;
    }

    /* 单点传感器的首版分类只表示热响应速度，后续可替换为完整模型。 */
    if (avg_positive_rate >= 15.0f || core->max_rate_c_per_min >= 28.0f) {
        core->pot_class = PG_POT_FAST;
    } else if (avg_positive_rate <= 3.0f && core->max_rate_c_per_min < 12.0f) {
        core->pot_class = PG_POT_SLOW;
    } else {
        core->pot_class = PG_POT_STANDARD;
    }
    core->profile = *pg_profile_for_class(core->pot_class);
    core->classified = 1;
    if (events) *events |= PG_EVENT_CLASSIFIED;
}

static void learn_boiling_reference(PgCore *core, uint64_t now_ms)
{
    if (core->boiling_ref_valid || !core->heating) return;
    if (core->filtered_temp_c < 80.0f || core->filtered_temp_c > 140.0f) {
        core->boiling_candidate_start_ms = 0;
        return;
    }
    if (fabsf(core->rate_c_per_min) > core->cfg.boiling_rate_abs_c_per_min) {
        core->boiling_candidate_start_ms = 0;
        return;
    }
    if (core->boiling_candidate_start_ms == 0) {
        core->boiling_candidate_start_ms = now_ms;
    } else if (now_ms - core->boiling_candidate_start_ms >= core->cfg.boiling_learn_ms) {
        core->boiling_ref_c = core->filtered_temp_c;
        core->boiling_ref_valid = 1;
    }
}

static uint32_t update_dry_burn_state(PgCore *core, uint64_t now_ms)
{
    uint32_t events = PG_EVENT_NONE;
    if (!core->pot_present || !core->heating) {
        if (!core->alarm_latched) {
            core->dry_risk_start_ms = 0;
            core->alarm_start_ms = 0;
            core->dry_risk_latched = 0;
            core->stage = core->pot_present ? PG_STAGE_NORMAL : PG_STAGE_WAITING;
        }
        return events;
    }

    const float reference = core->boiling_ref_valid
        ? core->boiling_ref_c : core->cfg.default_boiling_ref_c;
    const float relative_limit = reference + core->profile.dry_margin_c;
    const float absolute_limit = fminf(core->cfg.absolute_cutoff_c,
                                       core->profile.absolute_cutoff_c);
    const int absolute_danger = core->filtered_temp_c >= absolute_limit;
    const int trend_danger = core->filtered_temp_c >= relative_limit &&
                             core->rate_c_per_min >= core->profile.dry_rate_c_per_min;

    if (absolute_danger) {
        core->dry_risk_latched = 1;
        core->alarm_latched = 1;
        core->stage = PG_STAGE_ALARM;
        events |= PG_EVENT_DRY_RISK | PG_EVENT_ALARM_ON;
        return events;
    }

    if (!trend_danger) {
        if (!core->dry_risk_latched && !core->alarm_latched) {
            core->dry_risk_start_ms = 0;
            core->alarm_start_ms = 0;
            core->stage = (!core->classified && core->heating)
                ? PG_STAGE_HEATING : PG_STAGE_NORMAL;
        }
        return events;
    }

    if (core->dry_risk_start_ms == 0) core->dry_risk_start_ms = now_ms;
    if (now_ms - core->dry_risk_start_ms < core->cfg.dry_risk_hold_ms) {
        core->stage = PG_STAGE_DRY_RISK;
        return events;
    }

    if (!core->dry_risk_latched) {
        core->dry_risk_latched = 1;
        core->alarm_start_ms = now_ms;
        events |= PG_EVENT_DRY_RISK;
    }
    if (!core->alarm_latched && now_ms - core->alarm_start_ms >= core->cfg.alarm_hold_ms) {
        core->alarm_latched = 1;
        core->stage = PG_STAGE_ALARM;
        events |= PG_EVENT_ALARM_ON;
    } else if (core->alarm_latched) {
        core->stage = PG_STAGE_ALARM;
    } else {
        core->stage = PG_STAGE_DRY_RISK;
    }
    return events;
}

uint32_t pg_update(PgCore *core, const PgSample *sample)
{
    if (!core || !sample) return PG_EVENT_NONE;
    uint32_t events = pg_timer_update(core, sample->timestamp_ms);

    if (!sample->valid || !isfinite(sample->temp_c)) {
        core->stage = PG_STAGE_SENSOR_ERROR;
        return events | PG_EVENT_SENSOR_ERROR;
    }

    if (!sample->pot_present) {
        if (core->pot_present || core->alarm_latched) {
            events |= PG_EVENT_POT_REMOVED;
        }
        if (core->alarm_latched) events |= PG_EVENT_ALARM_OFF;
        core->pot_present = 0;
        core->heating = 0;
        core->stage = PG_STAGE_WAITING;
        core->classified = 0;
        core->pot_class = PG_POT_UNKNOWN;
        core->profile = *pg_profile_for_class(PG_POT_UNKNOWN);
        core->dry_risk_latched = 0;
        core->alarm_latched = 0;
        core->dry_risk_start_ms = 0;
        core->alarm_start_ms = 0;
        core->boiling_ref_valid = 0;
        core->has_sample = 0;
        return events;
    }

    if (!core->pot_present) {
        events |= PG_EVENT_POT_INSERTED;
        reset_measurement_cycle(core, sample);
    }
    core->pot_present = 1;
    core->heating = sample->heating != 0;

    if (!core->has_sample) {
        core->has_sample = 1;
        core->first_sample_ms = sample->timestamp_ms;
        core->last_sample_ms = sample->timestamp_ms;
        core->baseline_c = sample->temp_c;
        core->filtered_temp_c = sample->temp_c;
        core->last_temp_c = sample->temp_c;
        core->max_temp_c = sample->temp_c;
    } else {
        const uint64_t dt_ms = sample->timestamp_ms - core->last_sample_ms;
        const float dt_s = (float)dt_ms / 1000.0f;
        const float alpha = clampf(core->cfg.filter_alpha, 0.01f, 1.0f);
        core->filtered_temp_c += alpha * (sample->temp_c - core->filtered_temp_c);
        if (dt_s >= 0.05f && dt_s <= 120.0f) {
            core->rate_c_per_min = (core->filtered_temp_c - core->last_temp_c) / dt_s * 60.0f;
            if (core->rate_c_per_min > 0.0f) {
                core->rise_sum_c_per_min += core->rate_c_per_min;
                core->rate_samples++;
                if (core->rate_c_per_min > core->max_rate_c_per_min) {
                    core->max_rate_c_per_min = core->rate_c_per_min;
                }
            }
        }
        core->last_sample_ms = sample->timestamp_ms;
        core->last_temp_c = core->filtered_temp_c;
        if (core->filtered_temp_c > core->max_temp_c) core->max_temp_c = core->filtered_temp_c;
    }

    if (!core->classified && (core->heating || core->rate_c_per_min >= core->cfg.heating_rate_c_per_min)) {
        core->stage = PG_STAGE_HEATING;
    }
    classify_if_ready(core, sample->timestamp_ms, &events);
    learn_boiling_reference(core, sample->timestamp_ms);
    events |= update_dry_burn_state(core, sample->timestamp_ms);
    return events;
}

uint32_t pg_timer_start(PgCore *core, uint64_t now_ms, uint32_t seconds, const char *label)
{
    if (!core || seconds == 0) return PG_EVENT_NONE;
    core->timer.active = 1;
    core->timer.due_ms = now_ms + (uint64_t)seconds * 1000ull;
    memset(core->timer.label, 0, sizeof(core->timer.label));
    if (label) {
        strncpy(core->timer.label, label, sizeof(core->timer.label) - 1u);
    }
    return PG_EVENT_REMINDER;
}

void pg_timer_cancel(PgCore *core)
{
    if (!core) return;
    memset(&core->timer, 0, sizeof(core->timer));
}

uint32_t pg_timer_update(PgCore *core, uint64_t now_ms)
{
    if (!core || !core->timer.active) return PG_EVENT_NONE;
    if (now_ms < core->timer.due_ms) return PG_EVENT_NONE;
    core->timer.active = 0;
    core->last_timer_event_ms = now_ms;
    return PG_EVENT_TIMER_EXPIRED;
}
