#include "protocol.h"

#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#if defined(_WIN32)
#include <windows.h>
#else
#include <sys/time.h>
#endif

static const char *find_key(const char *json, const char *key)
{
    char pattern[64];
    const size_t key_len = strlen(key);
    if (key_len + 3u >= sizeof(pattern)) return NULL;
    snprintf(pattern, sizeof(pattern), "\"%s\"", key);
    return strstr(json, pattern);
}

static const char *value_start(const char *json, const char *key)
{
    const char *p = find_key(json, key);
    if (!p) return NULL;
    p = strchr(p, ':');
    if (!p) return NULL;
    p++;
    while (*p && isspace((unsigned char)*p)) p++;
    return p;
}

static int get_number(const char *json, const char *key, double *out)
{
    const char *p = value_start(json, key);
    char *end = NULL;
    if (!p || !out) return 0;
    *out = strtod(p, &end);
    return end != p;
}

static int get_string(const char *json, const char *key, char *out, size_t out_len)
{
    const char *p = value_start(json, key);
    size_t n = 0;
    if (!p || !out || out_len == 0 || *p != '"') return 0;
    p++;
    while (p[n] && p[n] != '"' && n + 1u < out_len) n++;
    if (p[n] != '"') return 0;
    memcpy(out, p, n);
    out[n] = '\0';
    return 1;
}

int protocol_parse_telemetry(const char *json, PgTelemetry *out)
{
    double timestamp = 0.0;
    double temp = 0.0;
    double humidity = 0.0;
    double heating = 0.0;
    double present = 1.0;
    if (!json || !out) return 0;
    memset(out, 0, sizeof(*out));
    if (!get_number(json, "timestamp_ms", &timestamp) ||
        !get_number(json, "temp_c", &temp)) return 0;
    (void)get_number(json, "ambient_humidity", &humidity);
    (void)get_number(json, "heating", &heating);
    (void)get_number(json, "pot_present", &present);
    (void)get_string(json, "device_id", out->device_id, sizeof(out->device_id));
    out->timestamp_ms = timestamp > 0.0 ? (uint64_t)timestamp : protocol_now_ms();
    out->temp_c = (float)temp;
    out->humidity_pct = (float)humidity;
    out->heating = heating != 0.0;
    out->pot_present = present != 0.0;
    return 1;
}

int protocol_parse_timer(const char *json, PgTimerCommand *out)
{
    double seconds = 0.0;
    if (!json || !out || !strstr(json, "\"type\"")) return 0;
    if (!strstr(json, "timer") || !get_number(json, "seconds", &seconds)) return 0;
    memset(out, 0, sizeof(*out));
    if (seconds < 1.0 || seconds > 7.0 * 24.0 * 3600.0) return 0;
    out->seconds = (uint32_t)seconds;
    (void)get_string(json, "label", out->label, sizeof(out->label));
    return 1;
}

uint64_t protocol_now_ms(void)
{
#if defined(_WIN32)
    /* GetTickCount 在旧版 MinGW/Windows SDK 中兼容性更好；32 位回绕对本项目
       的秒级 UDP 联调没有实际影响。 */
    return (uint64_t)GetTickCount();
#else
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return (uint64_t)tv.tv_sec * 1000ull + (uint64_t)tv.tv_usec / 1000ull;
#endif
}

const char *protocol_event_name(uint32_t event_bit)
{
    switch (event_bit) {
        case PG_EVENT_CLASSIFIED: return "CLASSIFIED";
        case PG_EVENT_POT_INSERTED: return "POT_INSERTED";
        case PG_EVENT_POT_REMOVED: return "POT_REMOVED";
        case PG_EVENT_DRY_RISK: return "DRY_RISK";
        case PG_EVENT_ALARM_ON: return "ALARM_ON";
        case PG_EVENT_ALARM_OFF: return "ALARM_OFF";
        case PG_EVENT_SENSOR_ERROR: return "SENSOR_ERROR";
        case PG_EVENT_TIMER_EXPIRED: return "TIMER_EXPIRED";
        case PG_EVENT_REMINDER: return "REMINDER";
        default: return "NONE";
    }
}

/*
 * Gemini-S1/openvela 通用 UDP 接收端。
 *
 * 默认监听 UDP 3333。把 core/ 和本目录加入官方 openvela app 的编译路径，
 * 再按 SDK 示例注册 main() 即可。代码只使用 POSIX socket 接口，避免依赖
 * 某一个版本的 RIVOTEK 工程目录。
 */

#include "pot_guard_core.h"
#include "protocol.h"
#include "platform_hooks.h"

#if defined(_WIN32)
#include <winsock2.h>
#include <ws2tcpip.h>
#else
#include <arpa/inet.h>
#endif
#include <errno.h>
#if !defined(_WIN32)
#include <netinet/in.h>
#endif
#include <stdio.h>
#include <string.h>
#if !defined(_WIN32)
#include <sys/socket.h>
#endif
#if !defined(_WIN32)
#include <sys/time.h>
#include <unistd.h>
#endif

#ifndef GG_UDP_PORT
#define GG_UDP_PORT 3333
#endif

static void gg_close_socket(int fd)
{
#if defined(_WIN32)
    closesocket((SOCKET)fd);
#else
    close(fd);
#endif
}

static void dispatch_events(uint32_t events, PgCore *core)
{
    const uint32_t bits[] = {
        PG_EVENT_CLASSIFIED, PG_EVENT_POT_INSERTED, PG_EVENT_POT_REMOVED,
        PG_EVENT_DRY_RISK, PG_EVENT_ALARM_ON, PG_EVENT_ALARM_OFF,
        PG_EVENT_SENSOR_ERROR, PG_EVENT_TIMER_EXPIRED, PG_EVENT_REMINDER
    };
    for (size_t i = 0; i < sizeof(bits) / sizeof(bits[0]); ++i) {
        if (events & bits[i]) gg_platform_event(bits[i], core);
    }
}

int gemini_guard_receiver_main(int argc, char **argv)
{
    (void)argc;
    (void)argv;
#if defined(_WIN32)
    WSADATA wsa;
    if (WSAStartup(MAKEWORD(2, 2), &wsa) != 0) return 1;
#endif
    int fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (fd < 0) {
        printf("socket failed errno=%d\n", errno);
        return 1;
    }

    int reuse = 1;
    (void)setsockopt(fd, SOL_SOCKET, SO_REUSEADDR,
#if defined(_WIN32)
                     (const char *)&reuse,
#else
                     &reuse,
#endif
                     sizeof(reuse));
#if defined(_WIN32)
    DWORD timeout_ms = 200;
    (void)setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO,
                     (const char *)&timeout_ms, sizeof(timeout_ms));
#else
    struct timeval timeout;
    timeout.tv_sec = 0;
    timeout.tv_usec = 200000;
    (void)setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout));
#endif

    struct sockaddr_in local;
    memset(&local, 0, sizeof(local));
    local.sin_family = AF_INET;
    local.sin_addr.s_addr = htonl(INADDR_ANY);
    local.sin_port = htons(GG_UDP_PORT);
    if (bind(fd, (struct sockaddr *)&local, sizeof(local)) < 0) {
        printf("bind UDP %d failed errno=%d\n", GG_UDP_PORT, errno);
        gg_close_socket(fd);
        return 1;
    }

    PgConfig cfg;
    PgCore core;
    pg_default_config(&cfg);
    pg_init(&core, &cfg);
    gg_platform_init();
    printf("gemini_guard_receiver: listening UDP %d\n", GG_UDP_PORT);

    for (;;) {
        char buf[512];
        const int n = recvfrom(fd, buf, (int)sizeof(buf) - 1, 0, NULL, NULL);
        const uint64_t now_ms = protocol_now_ms();
        if (n > 0) {
            buf[n] = '\0';
            PgTimerCommand timer_cmd;
            if (protocol_parse_timer(buf, &timer_cmd)) {
                const uint32_t timer_event = pg_timer_start(
                    &core, now_ms, timer_cmd.seconds, timer_cmd.label);
