#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""黑盒测试电脑端接收程序。

此脚本只验证 UDP 协议和状态机入口，不回放完整升温曲线，因此运行时间约两秒。
先用 CMake 构建 ``gemini_guard_receiver``，然后在本目录执行：

    python tools/test_integration.py

可以用 ``--exe`` 指定 openvela 模拟程序，或用 ``--port`` 指定空闲 UDP 端口。
"""

import argparse
import json
import queue
import socket
import subprocess
import sys
import threading
import time
from pathlib import Path


def _reader(stream, lines):
    try:
        for line in stream:
            lines.put(line.rstrip("\r\n"))
    finally:
        lines.put(None)


def _wait_for(lines, needle, timeout=3.0):
    end = time.monotonic() + timeout
    seen = []
    while time.monotonic() < end:
        try:
            line = lines.get(timeout=max(0.01, end - time.monotonic()))
        except queue.Empty:
            break
        if line is None:
            break
        seen.append(line)
        if needle in line:
            return seen
    raise AssertionError("未看到 {!r}；最近输出：{}".format(needle, seen[-8:]))


def _send(sock, port, payload):
    if isinstance(payload, str):
        payload = payload.encode("utf-8")
    sock.sendto(payload, ("127.0.0.1", port))


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--exe", type=Path,
                        default=Path(__file__).resolve().parents[1] /
                        "gemini_guard_receiver.exe")
    parser.add_argument("--port", type=int, default=0,
                        help="0 表示自动选择空闲端口")
    args = parser.parse_args()
    if not args.exe.is_file():
        raise SystemExit("找不到接收程序：{}；请先构建 gemini_guard_receiver".format(args.exe))
    if not 0 <= args.port <= 65535:
        parser.error("--port must be between 0 and 65535")

    # 让内核分配端口，关闭占用探测 socket 后立即交给 receiver。
    probe = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    probe.bind(("127.0.0.1", args.port))
    port = probe.getsockname()[1]
    probe.close()
    process = subprocess.Popen(
        [str(args.exe), "--port", str(port)], stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT, text=True, encoding="utf-8", errors="replace",
        bufsize=1)
    lines = queue.Queue()
    thread = threading.Thread(target=_reader, args=(process.stdout, lines), daemon=True)
    thread.start()
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        _wait_for(lines, "listening UDP", 3.0)

        # 正常遥测：应识别锅具插入并打印状态。
        _send(sock, port, {"type": "telemetry", "device_id": "IT", "timestamp_ms": 1000,
                           "temp_c": 25.0, "heating": 1, "pot_present": 1, "valid": 1})
        _wait_for(lines, "POT_INSERTED")

        # 畸形 JSON 不得导致接收线程退出。
        _send(sock, port, b"this is not json")
        _wait_for(lines, "invalid", 2.0)

        # valid=0 明确报告传感器错误；temp_c 为 null 用于模拟断线。
        _send(sock, port, {"type": "telemetry", "device_id": "IT", "timestamp_ms": 2000,
                           "temp_c": None, "heating": 1, "pot_present": 1, "valid": 0})
        _wait_for(lines, "SENSOR_ERROR", 2.0)

        # 定时命令不依赖遥测时间戳，真实等待约一秒后应只到期一次。
        _send(sock, port, {"type": "timer", "seconds": 1, "label": "IT"})
        _wait_for(lines, "REMINDER", 2.0)
        _wait_for(lines, "TIMER_EXPIRED", 2.5)
        print("test_integration: PASS")
    finally:
        sock.close()
        process.terminate()
        try:
            process.wait(timeout=2.0)
        except subprocess.TimeoutExpired:
            process.kill()
            process.wait()


if __name__ == "__main__":
    try:
        main()
    except (AssertionError, OSError) as error:
        print("test_integration: FAIL: {}".format(error), file=sys.stderr)
        raise SystemExit(1)

